const attempts=new Map<string,{count:number;reset:number}>();
// ponytail: in-memory limiter is per process; replace with a shared store when deploying multiple API instances.
const rateLimit=(name:string,max=5,windowMs=15*60*1000)=>(req:express.Request,res:express.Response,next:express.NextFunction)=>{const key=`${name}:${req.ip}`;const now=Date.now();const current=attempts.get(key);if(!current||current.reset<=now){attempts.set(key,{count:1,reset:now+windowMs});return next()}if(current.count>=max)return next(new AppError('Terlalu banyak percobaan. Coba lagi beberapa saat.',429));current.count++;next()};
