async function processReservationQueue(conn:PoolConnection,bookId:number){
  await conn.execute("UPDATE reservations SET status='EXPIRED' WHERE book_id=? AND status='NOTIFIED' AND expires_at<NOW()",[bookId]);
  const [available]=await conn.execute<RowDataPacket[]>("SELECT COUNT(*) total FROM book_copies WHERE book_id=? AND status='AVAILABLE' FOR UPDATE",[bookId]);
  const [notified]=await conn.execute<RowDataPacket[]>("SELECT COUNT(*) total FROM reservations WHERE book_id=? AND status='NOTIFIED' AND expires_at>NOW() FOR UPDATE",[bookId]);
  let slots=Math.max(0,Number(available[0].total)-Number(notified[0].total));
  if(!slots)return;
  const [settings]=await conn.execute<RowDataPacket[]>("SELECT setting_value FROM settings WHERE setting_key='reservation_hold_hours'");
  const holdHours=Number(settings[0]?.setting_value||24);
  const [waiting]=await conn.execute<RowDataPacket[]>("SELECT r.*,b.title FROM reservations r JOIN books b ON b.id=r.book_id WHERE r.book_id=? AND r.status='WAITING' ORDER BY r.queue_number,r.created_at LIMIT ? FOR UPDATE",[bookId,slots]);
  for(const reservation of waiting){
    await conn.execute("UPDATE reservations SET status='NOTIFIED',notified_at=NOW(),expires_at=DATE_ADD(NOW(),INTERVAL ? HOUR) WHERE id=?",[holdHours,reservation.id]);
    await conn.execute("INSERT INTO notifications(user_id,title,message,type,category,link) VALUES(?,?,?,?,?,?)",[reservation.user_id,'Buku reservasi tersedia',`Buku ${reservation.title} yang kamu reservasi sudah tersedia.`,'info','BOOK_AVAILABLE',`/student/reservations/${reservation.id}`]);
    slots--;
  }
}
const syncBookInventory=async(conn:PoolConnection,bookId:number)=>conn.execute(`UPDATE books b JOIN (
  SELECT book_id,COUNT(*) total,SUM(status='AVAILABLE') available FROM book_copies WHERE book_id=? GROUP BY book_id
) inventory ON inventory.book_id=b.id SET b.stock=inventory.total,b.stok=inventory.available,b.available=inventory.available,b.status=IF(inventory.available>0,'available','unavailable') WHERE b.id=?`,[bookId,bookId]);
async function setBookCopyTotal(conn:PoolConnection,bookId:number,target:number){
  const [counts]=await conn.execute<RowDataPacket[]>("SELECT COUNT(*) total,SUM(status<>'AVAILABLE') unavailable FROM book_copies WHERE book_id=? FOR UPDATE",[bookId]);
  const total=Number(counts[0]?.total||0),unavailable=Number(counts[0]?.unavailable||0);
  if(target<unavailable)throw new AppError(`Total copy tidak boleh kurang dari ${unavailable} copy yang sedang tidak tersedia.`,409);
  for(let i=total;i<target;i++)await conn.execute('INSERT INTO book_copies(book_id,copy_code,status) VALUES(?,?,\'AVAILABLE\')',[bookId,`BOOK-${bookId}-COPY-${Date.now()}-${i+1}`]);
  if(target<total){
    const removeCount=total-target;
    const [removable]=await conn.execute<RowDataPacket[]>(`SELECT c.id FROM book_copies c
      WHERE c.book_id=? AND c.status='AVAILABLE'
      AND NOT EXISTS(SELECT 1 FROM borrowing_copies bc WHERE bc.copy_id=c.id)
      AND NOT EXISTS(SELECT 1 FROM book_copy_history h WHERE h.copy_id=c.id)
      ORDER BY c.id DESC LIMIT ? FOR UPDATE`,[bookId,removeCount]);
    if(removable.length<removeCount)throw new AppError('Sebagian copy memiliki riwayat dan tidak dapat dihapus. Ubah status copy tersebut melalui Inventory.',409);
    if(removable.length)await conn.query(`DELETE FROM book_copies WHERE id IN (${removable.map(()=>'?').join(',')})`,removable.map(copy=>copy.id));
  }
  await syncBookInventory(conn,bookId);
}
const inventoryJoin=`LEFT JOIN (
  SELECT book_id,COUNT(*) total_copies,SUM(status='AVAILABLE') available_copies,SUM(status='BORROWED') borrowed_copies,
    SUM(status='LOST') lost_copies,SUM(status='DAMAGED') damaged_copies,SUM(status='MAINTENANCE') maintenance_copies
  FROM book_copies GROUP BY book_id
) inv ON inv.book_id=b.id`;
const inventoryFields=`,COALESCE(inv.total_copies,b.stock) total_copies,COALESCE(inv.available_copies,b.available) available_copies,
  COALESCE(inv.borrowed_copies,0) borrowed_copies,COALESCE(inv.lost_copies,0) lost_copies,
  COALESCE(inv.damaged_copies,0) damaged_copies,COALESCE(inv.maintenance_copies,0) maintenance_copies,
  CASE
    WHEN COALESCE(inv.total_copies,b.stock)>0 AND COALESCE(inv.lost_copies,0)=COALESCE(inv.total_copies,b.stock) THEN 'LOST'
    WHEN COALESCE(inv.lost_copies,0)>0 AND COALESCE(inv.available_copies,b.available)>0 THEN 'PARTIALLY_LOST'
    WHEN COALESCE(inv.available_copies,b.available)=0 THEN 'OUT_OF_STOCK'
    WHEN COALESCE(inv.available_copies,b.available)<=2 THEN 'LIMITED'
    ELSE 'AVAILABLE'
  END inventory_status`;
const reviewJoin=`LEFT JOIN (SELECT book_id,ROUND(AVG(rating),2) average_rating,COUNT(*) total_reviews FROM book_reviews WHERE status='VISIBLE' GROUP BY book_id) review_stats ON review_stats.book_id=b.id`;
const popularityJoin=`LEFT JOIN (SELECT id_buku,COALESCE(SUM(jumlah),0) borrow_count FROM detail_peminjaman GROUP BY id_buku) popularity ON popularity.id_buku=b.id`;
const reviewFields=`,COALESCE(review_stats.average_rating,0) average_rating,COALESCE(review_stats.total_reviews,0) total_reviews,COALESCE(popularity.borrow_count,0) borrow_count`;
const transactionId=(prefix:string)=>`${prefix}-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${Date.now().toString().slice(-6)}`;
const borrowingSelect=`SELECT p.*,
  p.id_peminjaman id, p.id_peminjaman transaction_id, p.id_anggota user_id,
  p.tanggal_pinjam borrow_date, p.tanggal_jatuh_tempo due_date,
  k.tanggal_kembali return_date, k.denda,
  u.name anggota_nama, u.name user_name, u.member_id, u.member_id user_member_id,
  u.email,u.phone,u.address,u.class,
  MIN(b.title) book_title, MIN(b.cover) book_cover,
  GROUP_CONCAT(CONCAT(b.title,' ×',d.jumlah) SEPARATOR ' | ') buku_ringkas
  FROM peminjaman p JOIN users u ON u.id=p.id_anggota
  LEFT JOIN detail_peminjaman d ON d.id_peminjaman=p.id_peminjaman
  LEFT JOIN books b ON b.id=d.id_buku
  LEFT JOIN pengembalian k ON k.id_peminjaman=p.id_peminjaman`;
const markLateBorrowings = async () => {
  await query(`INSERT INTO notifications (user_id,title,message,type,link)
    SELECT p.id_anggota, 'Peminjaman terlambat',
      CONCAT('Peminjaman ',p.id_peminjaman,' telah melewati jatuh tempo.'),
      'late', CONCAT('/student/borrowings/',p.id_peminjaman)
    FROM peminjaman p
    WHERE p.status='ACTIVE' AND p.tanggal_jatuh_tempo < NOW()
    AND NOT EXISTS (
      SELECT 1 FROM notifications n
      WHERE n.user_id=p.id_anggota AND n.type='late'
      AND n.link=CONCAT('/student/borrowings/',p.id_peminjaman)
    )`);
  await query(`INSERT INTO activity_logs(user_id,action,entity_type,entity_id,details)
    SELECT p.id_anggota,'OVERDUE','peminjaman',0,CONCAT('Peminjaman ',p.id_peminjaman,' melewati jatuh tempo')
    FROM peminjaman p WHERE p.status='ACTIVE' AND p.tanggal_jatuh_tempo<NOW()`);
  await query(`UPDATE peminjaman p LEFT JOIN settings s ON s.setting_key='late_fine'
    SET p.status='OVERDUE',p.late_days=GREATEST(1,CEIL(TIMESTAMPDIFF(SECOND,p.tanggal_jatuh_tempo,NOW())/86400)),
      p.fine_amount=GREATEST(1,CEIL(TIMESTAMPDIFF(SECOND,p.tanggal_jatuh_tempo,NOW())/86400))*CAST(COALESCE(s.setting_value,'0') AS DECIMAL(12,2))
    WHERE p.status IN ('ACTIVE','OVERDUE') AND p.tanggal_jatuh_tempo<NOW()`);
};
const cleanupOrphanedFiles=async()=>{const [users,books,ebooks]=await Promise.all([query<RowDataPacket[]>('SELECT photo,identity_file FROM users'),query<RowDataPacket[]>('SELECT cover,file_ebook FROM books'),query<RowDataPacket[]>('SELECT cover,file_path FROM ebooks')]);const referenced=new Set<string>();for(const row of [...users,...books,...ebooks])for(const value of Object.values(row))if(typeof value==='string'&&value)referenced.add(path.basename(value));const cutoff=Date.now()-24*60*60*1000;for(const directory of [uploadDir,privateUploadDir])for(const name of await fs.promises.readdir(directory)){if(referenced.has(name))continue;const file=path.join(directory,name);const stat=await fs.promises.stat(file).catch(()=>null);if(stat?.isFile()&&stat.mtimeMs<cutoff)await fs.promises.unlink(file).catch(()=>{})}};

