const registerSchema=z.object({name:z.string().min(3),email:z.string().email(),password:passwordSchema,nis:z.string().optional(),class:z.string().optional(),identity_type:z.enum(['STUDENT_CARD','KTP'])});
const saveIdentity=async(file:Express.Multer.File)=>{const ext=path.extname(file.originalname).toLowerCase();if(!fileMatchesContent(file.buffer,ext))throw new AppError('Foto identitas kosong, rusak, atau tidak sesuai tipe file.',400);const name=`identity-${Date.now()}-${randomBytes(12).toString('hex')}${ext}`;await fs.promises.writeFile(path.join(privateUploadDir,name),file.buffer,{flag:'wx'});return name};
app.post('/api/auth/register',rateLimit('register'),identityUpload.single('identity'),asyncRoute(async(req:express.Request,res:express.Response)=>{
  const parsed=registerSchema.safeParse(req.body);if(!parsed.success)throw new AppError('Data registrasi tidak valid.',400,parsed.error.errors);
  if(!req.file)throw new AppError('Foto identitas wajib diunggah.',400);
  const {name,email,password,nis,class:className,identity_type}=parsed.data;
  const exists = await query<RowDataPacket[]>('SELECT id FROM users WHERE email=?', [email]); if (exists.length) throw new AppError('Email sudah terdaftar.',409);
  const memberId = `STD-${Date.now().toString().slice(-6)}`;
  const identityFile=await saveIdentity(req.file);
  try{await query<ResultSetHeader>("INSERT INTO users(member_id,name,email,password,role,nis,class,status,identity_type,identity_file,identity_status) VALUES(?,?,?,?, 'student',?,?,'inactive',?,?, 'PENDING')",[memberId,name,email,await bcrypt.hash(password,12),nis||null,className||null,identity_type,identityFile])}catch(error){await fs.promises.unlink(path.join(privateUploadDir,identityFile)).catch(()=>{});throw error}
  sendSuccess(res,null,'Registrasi berhasil. Akun akan aktif setelah identitas disetujui admin.',201);
}));
app.post('/api/auth/login',rateLimit('login'),validate(z.object({email:z.string().email(),password:z.string().min(1)})),asyncRoute(async(req:express.Request,res:express.Response)=>{
  const users = await query<RowDataPacket[]>('SELECT * FROM users WHERE email=?',[req.body.email]); const user=users[0];
  if (!user || !(await bcrypt.compare(req.body.password,user.password))) throw new AppError('Email atau kata sandi tidak tepat.',401);
  if(user.identity_status==='PENDING')throw new AppError('Identitas Anda sedang menunggu verifikasi admin.',403);
  if(user.identity_status==='REJECTED')throw new AppError(`Identitas ditolak: ${user.identity_rejection_reason||'silakan unggah ulang dokumen.'}`,403);
  if(user.status!=='active')throw new AppError('Akun Anda tidak aktif.',403);
  await log(user.id,'LOGIN','user',user.id,'Login aplikasi'); sendSuccess(res,{user:safeUser(user),token:tokenFor(user)},'Login berhasil.');
}));
app.post('/api/auth/logout', authenticate, asyncRoute(async (req:AuthRequest,res) => { await log(req.user!.id,'LOGOUT','user',req.user!.id,'Logout aplikasi'); sendSuccess(res,null,'Logout berhasil.'); }));
app.post('/api/auth/forgot-password',rateLimit('forgot-password'),validate(z.object({email:z.string().email()})),asyncRoute(async(req:express.Request,res:express.Response)=>{
  const users = await query<RowDataPacket[]>('SELECT id,name FROM users WHERE email=?',[req.body.email]);
  let developmentResetUrl:string|undefined;
  if(users.length){const token=randomBytes(32).toString('hex');await query('DELETE FROM password_resets WHERE user_id=?',[users[0].id]);await query('INSERT INTO password_resets(user_id,token,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 1 HOUR))',[users[0].id,hashToken(token)]);if(process.env.NODE_ENV!=='production')developmentResetUrl=`/reset-password?token=${token}`}
  sendSuccess(res,developmentResetUrl?{development_reset_url:developmentResetUrl}:null,'Jika email terdaftar, instruksi pemulihan akan dikirim.');
}));
app.post('/api/auth/reset-password',rateLimit('reset-password'),validate(z.object({token:z.string().min(1),password:passwordSchema})),asyncRoute(async(req:express.Request,res:express.Response)=>{
  const rows = await query<RowDataPacket[]>('SELECT * FROM password_resets WHERE token=? AND expires_at>NOW()',[hashToken(req.body.token)]);
  if (!rows.length) throw new AppError('Token tidak valid atau sudah kedaluwarsa.',400);
  await query('UPDATE users SET password=? WHERE id=?',[await bcrypt.hash(req.body.password,12),rows[0].user_id]);
  await query('DELETE FROM password_resets WHERE user_id=?',[rows[0].user_id]);
  sendSuccess(res,null,'Kata sandi berhasil diperbarui. Silakan masuk dengan kata sandi baru.');
}));
app.post('/api/auth/identity/resubmit',rateLimit('identity-resubmit'),identityUpload.single('identity'),asyncRoute(async(req:express.Request,res:express.Response)=>{const parsed=z.object({email:z.string().email(),password:z.string().min(1),identity_type:z.enum(['STUDENT_CARD','KTP'])}).safeParse(req.body);if(!parsed.success||!req.file)throw new AppError('Email, kata sandi, jenis, dan foto identitas wajib diisi.',400);const users=await query<RowDataPacket[]>('SELECT * FROM users WHERE email=? AND role=\'student\'',[parsed.data.email]);const user=users[0];if(!user||!await bcrypt.compare(parsed.data.password,user.password))throw new AppError('Email atau kata sandi tidak tepat.',401);if(user.identity_status==='APPROVED')throw new AppError('Identitas sudah disetujui.',409);const file=await saveIdentity(req.file);const old=user.identity_file;await query("UPDATE users SET identity_type=?,identity_file=?,identity_status='PENDING',identity_rejection_reason=NULL,identity_verified_by=NULL,identity_verified_at=NULL WHERE id=?",[parsed.data.identity_type,file,user.id]);if(old)await fs.promises.unlink(path.join(privateUploadDir,path.basename(old))).catch(()=>{});sendSuccess(res,null,'Foto identitas berhasil dikirim ulang dan menunggu pemeriksaan.')}));
