// Transaction model: PEMINJAMAN -> DETAIL_PEMINJAMAN -> BUKU -> PENGEMBALIAN.
const transactionSchema=z.object({items:z.array(z.object({id_buku:z.coerce.number().int().positive(),jumlah:z.coerce.number().int().min(1).max(3).default(1)})).min(1).max(3),durasi:z.coerce.number().int().min(1).max(720),satuan:z.enum(['jam','hari'])});
type TransactionItem={id_buku:number;jumlah:number};

async function createTransaction(userId:number,items:TransactionItem[],durasi?:number,satuan:'jam'|'hari'='hari'){
  const conn=await getConnection();
  try{
    await conn.beginTransaction();
    const [settings]=await conn.execute<RowDataPacket[]>("SELECT setting_key,setting_value FROM settings WHERE setting_key IN ('borrow_duration','max_borrow')");
    const values=Object.fromEntries(settings.map(s=>[s.setting_key,s.setting_value]));
    const duration=durasi??Number(values.borrow_duration||7);
    const maxBorrow=Number(values.max_borrow||3);
    const merged=[...items.reduce((map,item)=>map.set(item.id_buku,{id_buku:item.id_buku,jumlah:(map.get(item.id_buku)?.jumlah||0)+item.jumlah}),new Map<number,TransactionItem>()).values()];
    const [active]=await conn.execute<RowDataPacket[]>("SELECT d.id_buku,d.jumlah FROM peminjaman p JOIN detail_peminjaman d ON d.id_peminjaman=p.id_peminjaman WHERE p.id_anggota=? AND p.status IN ('ACTIVE','OVERDUE') FOR UPDATE",[userId]);
    if(active.reduce((total,item)=>total+Number(item.jumlah),0)+merged.reduce((total,item)=>total+item.jumlah,0)>maxBorrow)throw new AppError('Batas peminjaman aktif tercapai.',409);
    if(merged.some(item=>active.some(current=>current.id_buku===item.id_buku)))throw new AppError('Salah satu buku masih sedang kamu pinjam.',409);
    for(const item of merged){
      const [books]=await conn.execute<RowDataPacket[]>('SELECT id,title FROM books WHERE id=? AND archived_at IS NULL FOR UPDATE',[item.id_buku]);
      const book=books[0];
      if(!book)throw new AppError('Buku tidak ditemukan.',404);
      const [copies]=await conn.execute<RowDataPacket[]>("SELECT id FROM book_copies WHERE book_id=? AND status='AVAILABLE' ORDER BY id LIMIT ? FOR UPDATE",[item.id_buku,item.jumlah]);
      if(copies.length<item.jumlah)throw new AppError(`Stok ${book.title} tidak mencukupi.`,409);
    }
    const id=transactionId('PJM');
    const durationHours=satuan==='hari'?duration*24:duration;
    await conn.execute("INSERT INTO peminjaman(id_peminjaman,id_anggota,tanggal_pinjam,tanggal_jatuh_tempo,status) VALUES(?,?,NOW(),DATE_ADD(NOW(),INTERVAL ? HOUR),'ACTIVE')",[id,userId,durationHours]);
    for(const item of merged){
      const [detail]=await conn.execute<ResultSetHeader>('INSERT INTO detail_peminjaman(id_peminjaman,id_buku,jumlah) VALUES(?,?,?)',[id,item.id_buku,item.jumlah]);
      const [copies]=await conn.execute<RowDataPacket[]>("SELECT id FROM book_copies WHERE book_id=? AND status='AVAILABLE' ORDER BY id LIMIT ? FOR UPDATE",[item.id_buku,item.jumlah]);
      for(const copy of copies){await conn.execute("UPDATE book_copies SET status='BORROWED' WHERE id=?",[copy.id]);await conn.execute('INSERT INTO borrowing_copies(id_detail,copy_id) VALUES(?,?)',[detail.insertId,copy.id]);await conn.execute("INSERT INTO book_copy_history(copy_id,from_status,to_status,id_peminjaman,changed_by,notes) VALUES(?,'AVAILABLE','BORROWED',?,?,?)",[copy.id,id,userId,'Copy dipinjam']);}
      await conn.execute("UPDATE reservations SET status='FULFILLED' WHERE user_id=? AND book_id=? AND status='NOTIFIED'",[userId,item.id_buku]);
      await syncBookInventory(conn,item.id_buku);
    }
    await conn.execute('INSERT INTO notifications(user_id,title,message,type,link) VALUES(?,?,?,?,?)',[userId,'Peminjaman berhasil',`Peminjaman ${id} berhasil dibuat.`,'borrow',`/student/borrowings/${id}`]);
    await conn.execute('INSERT INTO activity_logs(user_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)',[userId,'BORROW','peminjaman',0,`Membuat ${id}`]);
    await conn.commit();
    return {id_peminjaman:id,due_date:new Date(Date.now()+durationHours*3600000).toISOString(),duration,satuan};
  }catch(error){await conn.rollback();throw error}finally{conn.release()}
}

async function returnTransaction(id:string,actorId:number,actorRole:string){
  const conn=await getConnection();
  try{
    await conn.beginTransaction();
    const [rows]=await conn.execute<RowDataPacket[]>('SELECT * FROM peminjaman WHERE id_peminjaman=? OR legacy_borrowing_id=? FOR UPDATE',[id,id]);
    const borrowing=rows[0];
    if(!borrowing)throw new AppError('Peminjaman tidak ditemukan.',404);
    if(actorRole!=='admin'&&borrowing.id_anggota!==actorId)throw new AppError('Akses ditolak.',403);
    if(borrowing.status==='RETURNED')throw new AppError('Peminjaman ini sudah dikembalikan.',409);
    const [settings]=await conn.execute<RowDataPacket[]>("SELECT setting_value FROM settings WHERE setting_key='late_fine'");
    const lateDays=Math.max(0,Math.ceil((Date.now()-new Date(borrowing.tanggal_jatuh_tempo).getTime())/86400000));
    const fine=lateDays*Number(settings[0]?.setting_value||0);
    const returnStatus=lateDays>0?'Terlambat':'Dikembalikan';
    const [details]=await conn.execute<RowDataPacket[]>('SELECT * FROM detail_peminjaman WHERE id_peminjaman=?',[borrowing.id_peminjaman]);
    for(const item of details){const [copies]=await conn.execute<RowDataPacket[]>("SELECT c.id FROM borrowing_copies bc JOIN book_copies c ON c.id=bc.copy_id WHERE bc.id_detail=? AND c.status='BORROWED' FOR UPDATE",[item.id_detail]);for(const copy of copies){await conn.execute("UPDATE book_copies SET status='AVAILABLE' WHERE id=?",[copy.id]);await conn.execute("INSERT INTO book_copy_history(copy_id,from_status,to_status,id_peminjaman,changed_by,notes) VALUES(?,'BORROWED','AVAILABLE',?,?,?)",[copy.id,borrowing.id_peminjaman,actorId,'Copy dikembalikan']);}await syncBookInventory(conn,item.id_buku);await processReservationQueue(conn,item.id_buku);}
    const returnId=transactionId('KMB');
    await conn.execute('INSERT INTO pengembalian(id_pengembalian,id_peminjaman,tanggal_kembali,denda,late_days,status,payment_status) VALUES(?,?,NOW(),?,?,?,?)',[returnId,borrowing.id_peminjaman,fine,lateDays,returnStatus,fine>0?'UNPAID':'PAID']);
    await conn.execute("UPDATE peminjaman SET status='RETURNED',late_days=?,fine_amount=? WHERE id_peminjaman=?",[lateDays,fine,borrowing.id_peminjaman]);
    await conn.execute('INSERT INTO notifications(user_id,title,message,type,link) VALUES(?,?,?,?,?)',[borrowing.id_anggota,lateDays?'Pengembalian terlambat':'Pengembalian berhasil',`Pengembalian ${borrowing.id_peminjaman} diproses. Denda: Rp${fine.toLocaleString('id-ID')}.`,lateDays?'late':'return','/student/history']);
    await conn.execute('INSERT INTO activity_logs(user_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)',[actorId,'RETURN','peminjaman',0,`Memproses pengembalian ${borrowing.id_peminjaman}`]);
    await conn.commit();
    return {id_pengembalian:returnId,id_peminjaman:borrowing.id_peminjaman,denda:fine,late_days:lateDays,status:returnStatus};
  }catch(error){await conn.rollback();throw error}finally{conn.release()}
}
