app.get('/api/reservations',authenticate,asyncRoute(async(req:AuthRequest,res)=>{await query("UPDATE reservations SET status='EXPIRED' WHERE status='NOTIFIED' AND expires_at<NOW()");const admin=req.user!.role==='admin';const rows=await query<RowDataPacket[]>(`SELECT r.*,b.title book_title,b.cover book_cover,u.name user_name,
  CASE WHEN r.status='WAITING' THEN (SELECT COUNT(*)+1 FROM reservations ahead WHERE ahead.book_id=r.book_id AND ahead.status='WAITING' AND (ahead.queue_number<r.queue_number OR (ahead.queue_number=r.queue_number AND ahead.created_at<r.created_at))) ELSE NULL END queue_position
  FROM reservations r JOIN books b ON b.id=r.book_id JOIN users u ON u.id=r.user_id ${admin?'':'WHERE r.user_id=?'} ORDER BY r.created_at DESC`,admin?[]:[req.user!.id]);sendSuccess(res,rows)}));
app.post('/api/reservations',authenticate,authorize('student'),validate(reservationSchema),asyncRoute(async(req:AuthRequest,res)=>{const conn=await getConnection();try{await conn.beginTransaction();const [books]=await conn.execute<RowDataPacket[]>('SELECT id,title FROM books WHERE id=? FOR UPDATE',[req.body.book_id]);if(!books.length)throw new AppError('Buku tidak ditemukan.',404);const [available]=await conn.execute<RowDataPacket[]>("SELECT id FROM book_copies WHERE book_id=? AND status='AVAILABLE' LIMIT 1",[req.body.book_id]);if(available.length)throw new AppError('Buku masih tersedia dan dapat langsung dipinjam.',409);const [existing]=await conn.execute<RowDataPacket[]>("SELECT id FROM reservations WHERE user_id=? AND book_id=? AND status IN ('WAITING','NOTIFIED')",[req.user!.id,req.body.book_id]);if(existing.length)throw new AppError('Kamu sudah memiliki reservasi aktif untuk buku ini.',409);const [queue]=await conn.execute<RowDataPacket[]>("SELECT COALESCE(MAX(queue_number),0)+1 next_number FROM reservations WHERE book_id=?",[req.body.book_id]);const [result]=await conn.execute<ResultSetHeader>("INSERT INTO reservations(user_id,book_id,queue_number,status) VALUES(?,?,?,'WAITING')",[req.user!.id,req.body.book_id,queue[0].next_number]);await conn.execute("INSERT INTO notifications(user_id,title,message,type,category,link) VALUES(?,?,?,?,?,?)",[req.user!.id,'Reservasi dibuat',`Kamu masuk antrean buku ${books[0].title}.`,'info','RESERVATION',`/student/reservations/${result.insertId}`]);await conn.execute('INSERT INTO activity_logs(user_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)',[req.user!.id,'RESERVATION','reservation',result.insertId,`Reservasi ${books[0].title}`]);await conn.commit();sendSuccess(res,{id:result.insertId,queue_number:queue[0].next_number},'Reservasi berhasil dibuat.',201)}catch(error){await conn.rollback();throw error}finally{conn.release()}}));
app.put('/api/reservations/:id/status',authenticate,validate(z.object({status:z.enum(['FULFILLED','CANCELLED'])})),asyncRoute(async(req:AuthRequest,res)=>{const rows=await query<RowDataPacket[]>('SELECT * FROM reservations WHERE id=?',[req.params.id]);const reservation=rows[0];if(!reservation)throw new AppError('Reservasi tidak ditemukan.',404);if(req.user!.role!=='admin'&&reservation.user_id!==req.user!.id)throw new AppError('Akses ditolak.',403);if(req.user!.role!=='admin'&&req.body.status!=='CANCELLED')throw new AppError('Siswa hanya dapat membatalkan reservasi.',403);if(!['WAITING','NOTIFIED'].includes(reservation.status))throw new AppError('Reservasi sudah selesai.',409);await query('UPDATE reservations SET status=? WHERE id=?',[req.body.status,req.params.id]);await log(req.user!.id,req.body.status==='CANCELLED'?'CANCEL_RESERVATION':'FULFILL_RESERVATION','reservation',Number(req.params.id),`Memperbarui reservasi ${req.params.id}`);sendSuccess(res,null,'Status reservasi diperbarui.')}));

