app.get('/api/reports/monthly-borrowings',authenticate,authorize('admin'),asyncRoute(async(req,res)=>{await markLateBorrowings();const month=String(req.query.month||new Date().toISOString().slice(0,7));const rows=await query<RowDataPacket[]>(`${borrowingSelect} WHERE DATE_FORMAT(p.tanggal_pinjam,'%Y-%m')=? GROUP BY p.id_peminjaman ORDER BY p.tanggal_pinjam DESC`,[month]);const stats={total_borrowings:rows.length,total_returns:rows.filter(x=>x.return_date).length,active:rows.filter(x=>x.status==='ACTIVE').length,late:rows.filter(x=>x.status==='OVERDUE').length};sendSuccess(res,{month,stats,transactions:rows})}));
app.get('/api/reports/data',authenticate,authorize('admin'),asyncRoute(async(req,res)=>{const type=String(req.query.type||'borrowings');const from=/^\d{4}-\d{2}-\d{2}$/.test(String(req.query.from||''))?String(req.query.from):null;const to=/^\d{4}-\d{2}-\d{2}$/.test(String(req.query.to||''))?String(req.query.to):null;const status=req.query.status?String(req.query.status):null;const category=req.query.category?Number(req.query.category):null;let rows:RowDataPacket[];switch(type){case'books':rows=await query<RowDataPacket[]>('SELECT b.*,c.name category_name FROM books b LEFT JOIN categories c ON c.id=b.category_id WHERE (? IS NULL OR b.category_id=?) ORDER BY b.title',[category,category]);break;case'members':rows=await query<RowDataPacket[]>("SELECT id,member_id,name,email,class,status,created_at FROM users WHERE role='student' AND (? IS NULL OR status=?) ORDER BY name",[status,status]);break;case'returns':rows=await query<RowDataPacket[]>('SELECT k.*,p.id_anggota,u.name user_name FROM pengembalian k JOIN peminjaman p ON p.id_peminjaman=k.id_peminjaman JOIN users u ON u.id=p.id_anggota WHERE (? IS NULL OR DATE(k.tanggal_kembali)>=?) AND (? IS NULL OR DATE(k.tanggal_kembali)<=?) ORDER BY k.tanggal_kembali DESC',[from,from,to,to]);break;case'overdue':rows=await query<RowDataPacket[]>(`${borrowingSelect} WHERE p.status='OVERDUE' AND (? IS NULL OR DATE(p.tanggal_pinjam)>=?) AND (? IS NULL OR DATE(p.tanggal_pinjam)<=?) GROUP BY p.id_peminjaman ORDER BY p.tanggal_jatuh_tempo`,[from,from,to,to]);break;case'fines':rows=await query<RowDataPacket[]>('SELECT k.*,u.name user_name FROM pengembalian k JOIN peminjaman p ON p.id_peminjaman=k.id_peminjaman JOIN users u ON u.id=p.id_anggota WHERE k.denda>0 AND (? IS NULL OR k.payment_status=?) AND (? IS NULL OR DATE(k.tanggal_kembali)>=?) AND (? IS NULL OR DATE(k.tanggal_kembali)<=?) ORDER BY k.tanggal_kembali DESC',[status,status,from,from,to,to]);break;case'inventory':case'lost':case'damaged':{const inventoryStatus=type==='lost'?'LOST':type==='damaged'?'DAMAGED':status;rows=await query<RowDataPacket[]>('SELECT c.*,b.title book_title,cat.name category_name FROM book_copies c JOIN books b ON b.id=c.book_id LEFT JOIN categories cat ON cat.id=b.category_id WHERE (? IS NULL OR c.status=?) AND (? IS NULL OR b.category_id=?) ORDER BY b.title,c.copy_code',[inventoryStatus,inventoryStatus,category,category]);break}case'reservations':rows=await query<RowDataPacket[]>('SELECT r.*,b.title book_title,u.name user_name FROM reservations r JOIN books b ON b.id=r.book_id JOIN users u ON u.id=r.user_id WHERE (? IS NULL OR r.status=?) AND (? IS NULL OR DATE(r.created_at)>=?) AND (? IS NULL OR DATE(r.created_at)<=?) ORDER BY r.created_at DESC',[status,status,from,from,to,to]);break;default:rows=await query<RowDataPacket[]>(`${borrowingSelect} WHERE (? IS NULL OR p.status=?) AND (? IS NULL OR DATE(p.tanggal_pinjam)>=?) AND (? IS NULL OR DATE(p.tanggal_pinjam)<=?) GROUP BY p.id_peminjaman ORDER BY p.tanggal_pinjam DESC`,[status,status,from,from,to,to]);}sendSuccess(res,{type,filters:{from,to,status,category},rows})}));
